import { test, expect } from '@playwright/test';

test.describe('Countdown Timer', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body><div id="timer">10</div><button id="start">Start</button><button id="stop">Stop</button><script>let count = 10; let interval; document.getElementById("start").addEventListener("click", () => { interval = setInterval(() => { count--; document.getElementById("timer").textContent = count; if (count <= 0) clearInterval(interval); }, 1000); }); document.getElementById("stop").addEventListener("click", () => { clearInterval(interval); }); </script></body></html>');
  });

  test('should display initial countdown value', async ({ page }) => {
    const timer = page.getByText('10');
    await expect(timer).toBeVisible();
  });

  test('should update timer every second when started', async ({ page }) => {
    const startButton = page.getByRole('button', { name: 'Start' });
    await startButton.click();

    const timer = page.locator('#timer');

    // Wait for timer to update to 9
    await expect(timer).toContainText('9', { timeout: 2000 });

    // Verify it continues updating
    await expect(timer).toContainText('8', { timeout: 2000 });

    // Verify it continues to 7
    await expect(timer).toContainText('7', { timeout: 2000 });
  });

  test('should stop timer when stop button is clicked', async ({ page }) => {
    const startButton = page.getByRole('button', { name: 'Start' });
    const stopButton = page.getByRole('button', { name: 'Stop' });
    const timer = page.locator('#timer');

    await startButton.click();

    // Wait for timer to update
    await expect(timer).toContainText('9', { timeout: 2000 });

    // Stop the timer
    await stopButton.click();

    // Get current value
    const currentValue = await timer.textContent();

    // Wait and verify it doesn't change
    await page.waitForTimeout(1500);
    const newValue = await timer.textContent();

    expect(currentValue).toBe(newValue);
  });

  test('should countdown to zero and stop', async ({ page }) => {
    const startButton = page.getByRole('button', { name: 'Start' });
    await startButton.click();

    const timer = page.locator('#timer');

    // Wait for countdown to reach 0
    await expect(timer).toContainText('0', { timeout: 12000 });

    // Verify it stays at 0
    await page.waitForTimeout(1500);
    const finalValue = await timer.textContent();
    expect(finalValue).toBe('0');
  });
});
